import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Objects;
import java.util.PriorityQueue;

public final class HuffmanCoding {

    private HuffmanCoding() {
        // Utility class.
    }

    private static final class Node {
        final int frequency;
        final int order;
        final Node left;
        final Node right;

        Node(int frequency, int order) {
            this.frequency = frequency;
            this.order = order;
            this.left = null;
            this.right = null;
        }

        Node(Node left, Node right) {
            this.frequency = left.frequency + right.frequency;
            this.order = Math.min(left.order, right.order);
            this.left = left;
            this.right = right;
        }

        boolean isLeaf() {
            return left == null && right == null;
        }
    }

    private static final Comparator<Node> NODE_ORDER = Comparator
            .comparingInt((Node node) -> node.frequency)
            .thenComparingInt(node -> node.order);

    public static ArrayList<String> huffmanCodes(String symbols, int[] frequencies) {
        Objects.requireNonNull(symbols, "symbols must not be null");
        Objects.requireNonNull(frequencies, "frequencies must not be null");

        if (symbols.length() != frequencies.length) {
            throw new IllegalArgumentException("symbols and frequencies must have the same length");
        }

        ArrayList<String> codes = new ArrayList<>(frequencies.length);
        if (frequencies.length == 0) {
            return codes;
        }

        PriorityQueue<Node> queue = new PriorityQueue<>(NODE_ORDER);
        for (int i = 0; i < frequencies.length; i++) {
            queue.add(new Node(frequencies[i], i));
        }

        if (queue.size() == 1) {
            codes.add("0");
            return codes;
        }

        while (queue.size() > 1) {
            Node left = queue.poll();
            Node right = queue.poll();
            queue.add(new Node(left, right));
        }

        buildCodes(queue.peek(), new StringBuilder(), codes);
        return codes;
    }

    private static void buildCodes(Node node, StringBuilder prefix, List<String> codes) {
        if (node == null) {
            return;
        }

        if (node.isLeaf()) {
            codes.add(prefix.length() == 0 ? "0" : prefix.toString());
            return;
        }

        prefix.append('0');
        buildCodes(node.left, prefix, codes);
        prefix.setLength(prefix.length() - 1);

        prefix.append('1');
        buildCodes(node.right, prefix, codes);
        prefix.setLength(prefix.length() - 1);
    }

    public static void main(String[] args) {
        String symbols = "abcdef";
        int[] frequencies = {5, 9, 12, 13, 16, 45};

        ArrayList<String> codes = huffmanCodes(symbols, frequencies);
        System.out.println(String.join(" ", codes));
    }
}

import java.util.ArrayList;
import java.util.Comparator;
import java.util.Arrays;
import java.util.List;
import java.util.Objects;
import java.util.PriorityQueue;

public final class HuffmanCoding {

    private HuffmanCoding() {
        // Utility class.
    }

    private static final class Node {
        final int frequency;
        final int order;
        final int symbolIndex;
        final Node left;
        final Node right;

        Node(int frequency, int order, int symbolIndex) {
            this.frequency = frequency;
            this.order = order;
            this.symbolIndex = symbolIndex;
            this.left = null;
            this.right = null;
        }

        Node(Node left, Node right) {
            this.frequency = left.frequency + right.frequency;
            this.order = Math.min(left.order, right.order);
            this.symbolIndex = -1;
            this.left = left;
            this.right = right;
        }

        boolean isLeaf() {
            return left == null && right == null;
        }
    }

    private static final Comparator<Node> NODE_ORDER = Comparator
            .comparingInt((Node node) -> node.frequency)
            .thenComparingInt(node -> node.order);

    public static ArrayList<String> huffmanCodes(String symbols, int[] frequencies) {
        Objects.requireNonNull(symbols, "symbols must not be null");
        Objects.requireNonNull(frequencies, "frequencies must not be null");

        if (symbols.length() != frequencies.length) {
            throw new IllegalArgumentException("symbols and frequencies must have the same length");
        }

        if (frequencies.length == 0) {
            return new ArrayList<>();
        }

        validateFrequencies(frequencies);
        HuffmanTree tree = HuffmanTree.fromFrequencies(frequencies);
        return tree.codesInSymbolOrder(frequencies.length);
    }

    private static void validateFrequencies(int[] frequencies) {
        for (int frequency : frequencies) {
            if (frequency < 0) {
                throw new IllegalArgumentException("frequencies must be non-negative");
            }
        }
    }

    private static final class HuffmanTree {
        private final Node root;

        private HuffmanTree(Node root) {
            this.root = root;
        }

        static HuffmanTree fromFrequencies(int[] frequencies) {
            PriorityQueue<Node> queue = new PriorityQueue<>(NODE_ORDER);
            for (int i = 0; i < frequencies.length; i++) {
                queue.add(new Node(frequencies[i], i, i));
            }

            if (queue.size() == 1) {
                return new HuffmanTree(queue.peek());
            }

            while (queue.size() > 1) {
                Node left = queue.poll();
                Node right = queue.poll();
                queue.add(new Node(left, right));
            }

            return new HuffmanTree(queue.peek());
        }

        ArrayList<String> codesInSymbolOrder(int symbolCount) {
            String[] codes = new String[symbolCount];
            fillCodes(root, new StringBuilder(), codes);
            return new ArrayList<>(Arrays.asList(codes));
        }

        private void fillCodes(Node node, StringBuilder prefix, String[] codes) {
            if (node == null) {
                return;
            }

            if (node.isLeaf()) {
                codes[node.symbolIndex] = prefix.length() == 0 ? "0" : prefix.toString();
                return;
            }

            prefix.append('0');
            fillCodes(node.left, prefix, codes);
            prefix.setLength(prefix.length() - 1);

            prefix.append('1');
            fillCodes(node.right, prefix, codes);
            prefix.setLength(prefix.length() - 1);
        }
    }
}

